shell_commands.command:
cd /testbed && git apply --recount <<'PATCH'
diff --git a/src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java b/src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java
--- a/src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java
+++ b/src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java
@@ -1340,6 +1340,37 @@
     @Test
+    public void disposeBeforeInnerOnSubscribe() {
+        for (boolean delayErrors : new boolean[] { false, true }) {
+            PublishSubject<Integer> ps = PublishSubject.create();
+            PublishSubject<Integer> inner = PublishSubject.create();
+            TestObserver<Integer> to = new TestObserver<>();
+
+            Function<Integer, Observable<Integer>> mapper = v -> Observable.defer(() -> {
+                to.dispose();
+                return inner.scan(0, (a, b) -> a + b).map(w -> w);
+            });
+
+            Observable<Integer> result;
+            if (delayErrors) {
+                result = ps.switchMapDelayError(mapper);
+            } else {
+                result = ps.switchMap(mapper);
+            }
+            result.subscribe(to);
+
+            ps.onNext(1);
+
+            to.assertEmpty();
+            assertTrue(to.isDisposed());
+            assertFalse(ps.hasObservers());
+            assertFalse(inner.hasObservers());
+        }
+    }
+
+    @Test
     public void switchDuringOnNext() {
         PublishSubject<Integer> ps = PublishSubject.create();

PATCH
./gradlew --offline test --tests io.reactivex.rxjava3.internal.operators.observable.ObservableSwitchTest.disposeBeforeInnerOnSubscribe

cd /testbed && git apply --recount <<'PATCH'
diff --git a/src/main/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchMap.java b/src/main/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchMap.java
--- a/src/main/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchMap.java
+++ b/src/main/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchMap.java
@@ -348,10 +348,11 @@
         @Override
         public void onNext(R t) {
-            if (index == parent.unique) {
+            SimpleQueue<R> q = queue;
+            if (index == parent.unique && q != null) {
                 if (t != null) {
-                    queue.offer(t);
+                    q.offer(t);
                 }
                 parent.drain();
             }
         }
